  "exciting":[{w:"boring", d:"exciting 指令人兴奋的；boring 指令人厌烦的、无聊的，感受相反。"}],
  "expensive":[{w:"cheap", d:"expensive 指昂贵的；cheap 指便宜的，价格高低相反。"}],
  "fail":[{w:"succeed", d:"fail 是失败、不及格；succeed 是成功，成与败相反。"},{w:"pass", d:"pass 指及格、通过考试，与 fail 的不及格相对。"},{w:"accomplish", d:"fail 指失败；accomplish 指完成，两者语义相反。"},{w:"achieve", d:"fail 指失败；achieve 指实现，两者语义相反。"}],
  "fair":[{w:"unfair", d:"fair 指公平的；unfair 指不公平的，公正与否相反。"},{w:"partial", d:"partial 偏袒的、不公正的，与 fair 的一视同仁相反。"}],
  "fall":[{w:"rise", d:"fall 是落下、下降；rise 是上升、上涨，是降与升的对立。"}],
  "familiar":[{w:"strange", d:"familiar 指熟悉的；strange 指陌生的、奇怪的，熟悉与陌生相反。"},{w:"unfamiliar", d:"unfamiliar 不熟悉的、没见过的，与 familiar 的熟识相反。"}],
  "fast":[{w:"slow", d:"fast 指快的、迅速的；slow 指慢的、缓慢的，速度快慢相反。"}],
  "fat":[{w:"thin", d:"fat 指胖的；thin 指瘦的，体型胖瘦相反。"}],
  "few":[{w:"many", d:"few 指很少的、几乎没有；many 指许多的，两者都修饰可数名词复数，数量多少相反。"},{w:"numerous", d:"few 指很少的；numerous 指众多的，两者语义相反。"}],
  "fill":[{w:"empty", d:"fill 是装满、填满；empty 是倒空、腾空，装与倒相反。"}],
  "final":[{w:"first", d:"final 指最后的、最终的；first 指最初的、第一的，首尾相反。"},{w:"preliminary", d:"final 指最后的；preliminary 指初步的，两者语义相反。"}],
  "find":[{w:"lose", d:"find 是找到、发现；lose 是丢失、失去，得与失相反。"}],
  "finish":[{w:"begin", d:"finish 是完成、结束；begin 是开始。"},{w:"start", d:"start 是开始、着手，与 finish 的做完相对。"}],
  "fix":[{w:"break", d:"fix 是修理、修好；break 是弄坏、打破，修复与损坏相反。"},{w:"damage", d:"damage 损坏、破坏，与 fix 的修复相反。"}],
  "follow":[{w:"lead", d:"follow 是跟随、跟着；lead 是带领、引导，跟与带相反。"},{w:"precede", d:"precede 走在前面、先于，与 follow 的跟在后面相反。"}],
  "foreign":[{w:"domestic", d:"foreign 指外国的、外来的；domestic 指国内的、本国的。"},{w:"native", d:"native 本地的、土生土长的，与 foreign 的外来相反。"}],
  "forget":[{w:"remember", d:"forget 是忘记；remember 是记得、记住，遗忘与记忆相反。"},{w:"recall", d:"recall 回想起、召回，与 forget 的遗忘相反。"}],
  "forward":[{w:"backward", d:"forward 指向前；backward 指向后，方向相反。"}],
  "free":[{w:"busy", d:"free 指空闲的、自由的；busy 指忙碌的，有空与忙碌相反。"},{w:"compel", d:"free 指自由的；compel 指强迫，两者语义相反。"}],
  "fresh":[{w:"stale", d:"fresh 指新鲜的；stale 指不新鲜的、陈旧的，食品新鲜度相反。"}],
  "friendly":[{w:"unfriendly", d:"friendly 指友好的、友善的；unfriendly 指不友好的、冷漠的。"},{w:"hostile", d:"friendly 友好的、友善的；hostile 敌对的、怀有敌意的。"}],
  "full":[{w:"empty", d:"full 指满的、吃饱的；empty 指空的，满与空相反。"},{w:"hungry", d:"full 指满的；hungry 指饥饿的，两者语义相反。"}],
  "give":[{w:"take", d:"give 是给、赠给；take 是拿、取走，给与取相反。"},{w:"receive", d:"receive 是收到、接到，是 give 的另一端。"}],
  "glad":[{w:"sad", d:"glad 指高兴的、乐意的；sad 指悲伤的、难过的，心情相反。"}],
  "go":[{w:"come", d:"go 是去、走；come 是来，方向相反。"},{w:"stay", d:"stay 是停留、待着不动，与 go 的离开相对。"}],
  "good":[{w:"bad", d:"good 指好的、优秀的；bad 指坏的、糟糕的，是最常用的褒贬反义对。"}],
  "handsome":[{w:"ugly", d:"handsome 指英俊的、漂亮的；ugly 指丑陋的、难看的。"}],
