  "female":[{w:"male", d:"female 女性的、雌性的；male 男性的、雄性的。"}],
  "float":[{w:"sink", d:"float 漂浮、浮在水面；sink 下沉、沉下去。"}],
  "fold":[{w:"unfold", d:"fold 折叠、合拢；unfold 展开、摊开，同词根一正一反。"}],
  "forbid":[{w:"allow", d:"forbid 禁止、不许；allow 允许、让做。"},{w:"permit", d:"permit 准许、许可，与 forbid 的明令不许相反。"},{w:"authorize", d:"forbid 指禁止；authorize 指授权，两者语义相反。"}],
  "forgive":[{w:"blame", d:"forgive 原谅、宽恕；blame 责怪、把责任推给对方。"},{w:"punish", d:"punish 惩罚、处罚，与 forgive 的免于追究相反。"}],
  "formal":[{w:"informal", d:"formal 正式的、礼节性的；informal 非正式的、随便的。"},{w:"casual", d:"casual 随意的、休闲的，与 formal 的郑重正式相反。"}],
