  "pollute":[{w:"purify", d:"pollute 污染、弄脏；purify 净化、使洁净。"},{w:"clean", d:"clean 清洁、弄干净，与 pollute 的污染相反。"}],
  "possess":[{w:"lack", d:"possess 拥有、具有；lack 缺少、没有。"}],
  "potential":[{w:"actual", d:"potential 潜在的、可能的；actual 实际的、已经发生的。"}],
  "praise":[{w:"criticize", d:"praise 赞扬、表扬；criticize 批评、挑毛病。"},{w:"blame", d:"blame 责怪、归咎于，与 praise 的称赞相反。"},{w:"complain", d:"praise 指赞扬；complain 指抱怨，两者语义相反。"}],
  "preserve":[{w:"destroy", d:"preserve 保护、保存下来；destroy 破坏、毁掉。"},{w:"abandon", d:"abandon 丢弃、放弃不管，与 preserve 的留存相反。"},{w:"transform", d:"preserve 指保护；transform 指转变，两者语义相反。"}],
