  "satisfy":[{w:"dissatisfy", d:"satisfy 使满意；dissatisfy 使不满，同词根一正一反。"},{w:"disappoint", d:"disappoint 使失望，与 satisfy 的合乎期望相反。"}],
  "secure":[{w:"insecure", d:"secure 安全的、牢固的；insecure 不安全的、不牢靠的。"},{w:"unsafe", d:"unsafe 危险的、不安全的。"}],
  "seize":[{w:"release", d:"seize 抓住、夺取；release 放开、释放。"}],
  "shrink":[{w:"expand", d:"shrink 缩小、收缩；expand 扩大、膨胀。"},{w:"grow", d:"grow 增长、变大，与 shrink 的变小相反。"}],
