  "sincere":[{w:"insincere", d:"sincere 真诚的、诚恳的；insincere 虚情假意的、不真诚的。"}],
  "slight":[{w:"considerable", d:"slight 轻微的、细小的；considerable 相当大的、可观的。"},{w:"serious", d:"serious 严重的、不轻的，与 slight 的微不足道相反。"}],
  "smooth":[{w:"rough", d:"smooth 光滑的、顺利的；rough 粗糙的、崎岖的。"}],
  "thorough":[{w:"careless", d:"thorough 彻底的、细致的；careless 粗心的、马虎的。"},{w:"superficial", d:"superficial 表面的、浅尝辄止的，与 thorough 的深入彻底相反。"}],
  "tough":[{w:"easy", d:"tough 艰难的、棘手的；easy 容易的、轻松的。"},{w:"tender", d:"tender 柔嫩的、温柔的，与 tough 的坚硬、强硬相反。"},{w:"fragile", d:"tough 指艰难的；fragile 指易碎的，两者语义相反。"}],
  "ultimate":[{w:"initial", d:"ultimate 最终的、最后的；initial 最初的、开头的。"}],
  "valid":[{w:"invalid", d:"valid 有效的、站得住脚的；invalid 无效的、作废的。"}],
  "vanish":[{w:"appear", d:"vanish 消失、突然不见；appear 出现、露面。"},{w:"arise", d:"vanish 指消失；arise 指出现，两者语义相反。"},{w:"emerge", d:"vanish 指消失；emerge 指出现，两者语义相反。"}],
  "vital":[{w:"trivial", d:"vital 至关重要的、生死攸关的；trivial 微不足道的。"},{w:"unimportant", d:"unimportant 不重要的，与 vital 的极其重要相反。"}],
  "vulnerable":[{w:"strong", d:"vulnerable 脆弱的、易受伤害的；strong 强壮的、有抵抗力的。"}],
  "withdraw":[{w:"deposit", d:"withdraw 取出、提款；deposit 存入、存款。"},{w:"advance", d:"advance 前进、推进，与 withdraw 的后撤相反。"},{w:"participate", d:"withdraw 指撤回；participate 指参加，两者语义相反。"}],
  "abrupt":[{w:"gradual", d:"abrupt 指突然发生、毫无预兆；gradual 指逐渐的，强调过程缓慢。"}],
