  "adjacent":[{w:"distant", d:"adjacent 指紧挨着、毗连；distant 指相隔很远。"}],
  "adverse":[{w:"favorable", d:"adverse 指不利的、有害的；favorable 指有利的、顺利的。"},{w:"favourable", d:"adverse 指不利的、有害的；favourable 指有利的、有利助益的。"}],
  "advocate":[{w:"oppose", d:"advocate 指提倡拥护；oppose 指反对，立场正好相反。"}],
  "alter":[{w:"maintain", d:"alter 指改变、改动；maintain 指维持原样不变。"}],
  "ambiguous":[{w:"explicit", d:"ambiguous 指含糊、可作多种解释；explicit 指明确直白、不留歧义。"},{w:"unambiguous", d:"ambiguous 指模棱两可、含糊的；unambiguous 指毫不含糊、意思唯一。"}],
  "ample":[{w:"insufficient", d:"ample 指充裕有余；insufficient 指不够用。"}],
  "applaud":[{w:"criticize", d:"applaud 指鼓掌称赞；criticize 指批评指责，一个夸一个批。"}],
  "applicable":[{w:"inapplicable", d:"applicable 指适用于该情况；inapplicable 指不适用。"}],
  "barren":[{w:"fertile", d:"barren 指土地贫瘠、不能生育；fertile 指肥沃、能生育。"}],
  "bizarre":[{w:"normal", d:"bizarre 指离奇古怪、反常；normal 指正常普通。"}],
  "bleak":[{w:"promising", d:"bleak 指前景暗淡荒凉；promising 指有希望、有前途。"}],
  "blend":[{w:"separate", d:"blend 指混合成一体；separate 指把混在一起的成分分开。"}],
  "bloom":[{w:"wither", d:"bloom 指开花、繁盛；wither 指枯萎凋谢，盛与衰相对。"}],
  "blunt":[{w:"sharp", d:"blunt 指刀口钝；sharp 指锋利，引申为迟钝与敏锐的对立。"}],
  "blur":[{w:"clarify", d:"blur 指使模糊不清；clarify 指把问题讲清楚。"}],
  "boom":[{w:"slump", d:"boom 指经济繁荣、迅速增长；slump 指陷入低迷衰退。"}],
  "boost":[{w:"reduce", d:"boost 指促进提高；reduce 指减少降低。"}],
  "brilliant":[{w:"dull", d:"brilliant 指明亮的、才华出众的；dull 指暗淡的、平庸的。"}],
  "brisk":[{w:"sluggish", d:"brisk 指轻快活跃；sluggish 指迟缓倦怠。"}],
  "brutal":[{w:"humane", d:"brutal 指残忍野蛮；humane 指仁慈人道。"}],
  "capture":[{w:"release", d:"capture 指捕获抓住；release 指释放放走。"},{w:"escape", d:"capture 指捕获；escape 指逃跑，两者语义相反。"}],
  "casual":[{w:"formal", d:"casual 指随意休闲；formal 指正式庄重，多用于穿着与场合。"}],
  "cautious":[{w:"reckless", d:"cautious 指谨慎小心；reckless 指鲁莽、不顾后果。"},{w:"bold", d:"cautious 指谨慎的；bold 指大胆的，两者语义相反。"}],
  "cherish":[{w:"despise", d:"cherish 指珍爱看重；despise 指鄙视轻蔑。"}],
  "chronic":[{w:"acute", d:"chronic 指慢性的、长期的；acute 指急性的、发作猛烈的。"}],
  "clumsy":[{w:"graceful", d:"clumsy 指动作笨拙；graceful 指动作优雅协调。"},{w:"elegant", d:"clumsy 指笨拙的；elegant 指优雅的，两者语义相反。"}],
  "coherent":[{w:"incoherent", d:"coherent 指连贯有条理；incoherent 指语无伦次、前后不搭。"}],
  "collaborate":[{w:"compete", d:"collaborate 指合作共事；compete 指彼此竞争。"}],
  "degrade":[{w:"upgrade", d:"degrade 指降低等级、使降格；upgrade 指升级提高。"}],
  "deliberate":[{w:"accidental", d:"deliberate 指故意为之；accidental 指出于偶然、无意发生。"},{w:"random", d:"deliberate 指故意的；random 指随机的，两者语义相反。"}],
  "delicate":[{w:"sturdy", d:"delicate 指纤巧易损；sturdy 指结实牢固。"}],
  "deplete":[{w:"replenish", d:"deplete 指把资源耗尽；replenish 指把它重新补充回来。"}],
  "deprive":[{w:"provide", d:"deprive 指剥夺、让人失去；provide 指提供、给予。"}],
  "descend":[{w:"ascend", d:"descend 指下降、下来；ascend 指上升。"},{w:"rise", d:"rise 指升起上涨，与 descend 的往下走方向相反。"},{w:"climb", d:"descend 指下降；climb 指爬，两者语义相反。"}],
  "deteriorate":[{w:"improve", d:"deteriorate 指恶化变坏；improve 指改善变好。"}],
  "deviate":[{w:"conform", d:"deviate 指偏离正轨；conform 指遵从规范、与大家保持一致。"}],
  "dilute":[{w:"concentrate", d:"dilute 指稀释变淡；concentrate 指浓缩变浓。"}],
  "diminish":[{w:"increase", d:"diminish 指减少减弱；increase 指增加。"}],
  "disclose":[{w:"conceal", d:"disclose 指透露公开；conceal 指隐瞒隐藏。"}],
