  "eligible":[{w:"ineligible", d:"eligible 指符合条件、有资格；ineligible 指不够格。"}],
  "eminent":[{w:"obscure", d:"eminent 指名望显赫、地位突出；obscure 指默默无闻。"}],
  "emit":[{w:"absorb", d:"emit 指发出、散发；absorb 指吸收进来。"}],
  "empirical":[{w:"theoretical", d:"empirical 指来自经验和实证；theoretical 指停留在理论推演。"}],
  "endorse":[{w:"oppose", d:"endorse 指赞同、公开支持；oppose 指反对。"}],
