  "ethical":[{w:"unethical", d:"ethical 指合乎道德伦理；unethical 指不道德。"}],
  "evaporate":[{w:"condense", d:"evaporate 指蒸发变成气体；condense 指凝结成液体。"}],
  "exaggerate":[{w:"understate", d:"exaggerate 指夸大其词；understate 指轻描淡写。"}],
  "exceptional":[{w:"ordinary", d:"exceptional 指出类拔萃、异乎寻常；ordinary 指普通平常。"}],
