  "hollow":[{w:"solid", d:"hollow 指中间是空的；solid 指实心坚固。"}],
  "hostile":[{w:"friendly", d:"hostile 指怀有敌意；friendly 指友善亲切。"}],
  "humble":[{w:"arrogant", d:"humble 指谦逊低调；arrogant 指傲慢自大。"},{w:"proud", d:"proud 指骄傲自得，与 humble 的谦卑相对。"}],
  "humid":[{w:"dry", d:"humid 指空气潮湿；dry 指干燥。"}],
