  "laborious":[{w:"easy", d:"laborious 指费时费力；easy 指轻松容易。"}],
  "lament":[{w:"rejoice", d:"lament 指哀悼痛惜；rejoice 指欢欣庆祝。"}],
  "latter":[{w:"former", d:"latter 指两者中的后者；former 指前者。"}],
  "lavish":[{w:"frugal", d:"lavish 指奢华挥霍；frugal 指节俭朴素。"}],
  "legitimate":[{w:"illegal", d:"legitimate 指合法正当；illegal 指违法。"}],
  "lengthy":[{w:"brief", d:"lengthy 指冗长；brief 指简短，篇幅长短相对。"},{w:"concise", d:"lengthy 指冗长的；concise 指简明的，两者语义相反。"}],
  "lenient":[{w:"strict", d:"lenient 指宽容从宽；strict 指严格、要求高。"},{w:"severe", d:"lenient 指宽容的；severe 指严重的，两者语义相反。"},{w:"rigorous", d:"lenient 指宽容的；rigorous 指严格的，两者语义相反。"}],
  "liberate":[{w:"oppress", d:"liberate 指解放、使人自由；oppress 指压迫。"},{w:"enslave", d:"enslave 指奴役，与 liberate 的解放正好相反。"}],
  "literal":[{w:"figurative", d:"literal 指字面意思；figurative 指比喻、引申的意思。"}],
  "malicious":[{w:"benevolent", d:"malicious 指怀有恶意；benevolent 指善意仁慈。"}],
  "maternal":[{w:"paternal", d:"maternal 指母亲一方的、母系的；paternal 指父亲一方的、父系的。"}],
  "medieval":[{w:"modern", d:"medieval 指中世纪的；modern 指现代的。"}],
  "mediocre":[{w:"excellent", d:"mediocre 指平庸一般；excellent 指出色优秀。"}],
  "merit":[{w:"flaw", d:"merit 指优点、可取之处；flaw 指缺陷、不足。"}],
  "meticulous":[{w:"careless", d:"meticulous 指一丝不苟；careless 指粗心大意。"}],
  "miniature":[{w:"giant", d:"miniature 指微缩的、极小的；giant 指巨大的。"}],
  "minimal":[{w:"maximal", d:"minimal 指最小的、极少的；maximal 指最大的。"}],
  "mortal":[{w:"immortal", d:"mortal 指会死的、凡人的；immortal 指不朽永生的。"}],
  "mundane":[{w:"extraordinary", d:"mundane 指平凡单调；extraordinary 指非凡出众。"}],
  "naive":[{w:"sophisticated", d:"naive 指天真幼稚、缺乏经验；sophisticated 指老练世故。"}],
  "nasty":[{w:"pleasant", d:"nasty 指令人厌恶；pleasant 指令人愉快。"}],
  "negligible":[{w:"significant", d:"negligible 指小到可以忽略；significant 指重要、显著。"}],
  "nominal":[{w:"actual", d:"nominal 指名义上、挂名的；actual 指实际上的。"}],
  "notorious":[{w:"renowned", d:"notorious 指因坏事而声名狼藉；renowned 指因好事而闻名。"}],
  "obedient":[{w:"disobedient", d:"obedient 指听话服从；disobedient 指不服从。"}],
  "obese":[{w:"thin", d:"obese 指过于肥胖；thin 指瘦。"}],
  "obscure":[{w:"clear", d:"obscure 指晦涩难懂；clear 指清楚明白。"},{w:"famous", d:"famous 指有名，与 obscure 的默默无闻相对。"},{w:"obvious", d:"obscure 指晦涩难懂、不出名的；obvious 指明显的、一目了然的。"},{w:"apparent", d:"obscure 指模糊的；apparent 指明显的，两者语义相反。"},{w:"clarify", d:"obscure 指模糊的；clarify 指澄清，两者语义相反。"},{w:"eminent", d:"obscure 指模糊的；eminent 指著名的，两者语义相反。"},{w:"prominent", d:"obscure 指模糊的；prominent 指显著的，两者语义相反。"}],
  "obsolete":[{w:"modern", d:"obsolete 指过时淘汰；modern 指时新、合乎当下。"}],
  "occasional":[{w:"frequent", d:"occasional 指偶尔发生；frequent 指频繁发生。"},{w:"constant", d:"occasional 指偶尔的；constant 指不断的，两者语义相反。"}],
  "optional":[{w:"compulsory", d:"optional 指自由选择、非强制；compulsory 指强制必修。"},{w:"essential", d:"optional 指可选的；essential 指必要的，两者语义相反。"}],
  "oral":[{w:"written", d:"oral 指口头的；written 指书面的。"}],
  "outstanding":[{w:"ordinary", d:"outstanding 指出众卓越；ordinary 指平常普通。"}],
  "parallel":[{w:"perpendicular", d:"parallel 指两线平行永不相交；perpendicular 指两线垂直相交。"}],
  "partial":[{w:"complete", d:"partial 指部分的、不完全的；complete 指完整的。"},{w:"whole", d:"partial 指部分的、偏袒的；whole 指整体的、全部的。"},{w:"fair", d:"partial 指部分的；fair 指公平的，两者语义相反。"},{w:"entire", d:"partial 指部分的；entire 指全部的，两者语义相反。"},{w:"comprehensive", d:"partial 指部分的；comprehensive 指全面的，两者语义相反。"}],
  "peculiar":[{w:"ordinary", d:"peculiar 指奇特少见；ordinary 指普通寻常。"}],
